15	// evalCode compiles and executes code, returning the result
16	func evalCode(source string) (object.Object, error) {
17		l := lexer.New(source)
18		p := parser.New(l)
19		program := p.ParseProgram()
20	
21		if len(p.Errors()) > 0 {
22			return nil, fmt.Errorf("parse error: %s", p.Errors()[0])
23		}
24	
25		ch := checker.New()
26		ch.Check(program)
27	
28		if len(ch.Errors()) > 0 {
29			return nil, fmt.Errorf("check error: %s", ch.Errors()[0])
30		}
31	
32		c := compiler.New(ch.GlobalScope())
33		c.Compile(program)
34	
35		if len(c.Errors()) > 0 {
36			return nil, fmt.Errorf("compile error: %s", c.Errors()[0])
37		}
38	
39		v := vm.New(c.Bytecode(), c.Constants())
40		if err := v.Run(); err != nil {
41			return nil, err
42		}
43	
44		return v.LastPoppedStackElem(), nil
45	}
