281	// checkFunctionLiteral checks a function literal
282	func (c *Checker) checkFunctionLiteral(expr *ast.FunctionLiteral) Type {
283		// Push new scope for function
284		c.symtab.PushScope()
285	
286		// Define parameters
287		paramTypes := make([]Type, len(expr.Parameters))
288		for i, param := range expr.Parameters {
289			paramTypes[i] = TypeAny // Parameters are inferred as Any by default
290			c.symtab.Define(param.Value, SymbolParameter, TypeAny, false)
291		}
292	
293		// Check function body
294		returnType := c.checkBlockStatement(expr.Body)
295		if returnType == nil {
296			returnType = TypeVoid
297		}
298	
299		// Pop function scope
300		c.symtab.PopScope()
301	
302		return NewFunctionType(paramTypes, returnType)
303	}
