305	// checkPrefixExpression checks a prefix expression
306	func (c *Checker) checkPrefixExpression(expr *ast.PrefixExpression) Type {
307		rightType := c.checkExpression(expr.Right)
308	
309		switch expr.Operator {
310		case "!":
311			if !TypesEqual(rightType, TypeBool) && !TypesEqual(rightType, TypeAny) {
312				c.addError("! operator requires boolean, got %s", rightType.String())
313			}
314			return TypeBool
315		case "-":
316			if !TypesEqual(rightType, TypeInt) && !TypesEqual(rightType, TypeFloat) && !TypesEqual(rightType, TypeAny) {
317				c.addError("- operator requires number, got %s", rightType.String())
318			}
319			return rightType
320		case "+":
321			if !TypesEqual(rightType, TypeInt) && !TypesEqual(rightType, TypeFloat) && !TypesEqual(rightType, TypeAny) {
322				c.addError("+ operator requires number, got %s", rightType.String())
323			}
324			return rightType
325		case "~":
326			if !TypesEqual(rightType, TypeInt) && !TypesEqual(rightType, TypeAny) {
327				c.addError("~ operator requires int, got %s", rightType.String())
328			}
329			return TypeInt
330		default:
331			c.addError("unknown prefix operator: %s", expr.Operator)
332			return TypeAny
333		}
334	}
335	
336	// checkInfixExpression checks an infix expression
337	func (c *Checker) checkInfixExpression(expr *ast.InfixExpression) Type {
338		leftType := c.checkExpression(expr.Left)
339		rightType := c.checkExpression(expr.Right)
340	
341		switch expr.Operator {
342		case "+":
343			// + works on same types (numbers with numbers, strings with strings)
344			if isNumber(leftType) && isNumber(rightType) {
345				return leftType
346			}
347			if TypesEqual(leftType, TypeString) && TypesEqual(rightType, TypeString) {
348				return leftType
349			}
350			c.addError("+ operator requires same types (numbers or strings), got %s and %s",
351				leftType.String(), rightType.String())
352			return leftType
353		case "-", "*", "/", "%":
354			// Arithmetic operators require numbers
355			if !isNumber(leftType) || !isNumber(rightType) {
356				c.addError("%s operator requires numbers, got %s and %s",
357					expr.Operator, leftType.String(), rightType.String())
358			}
359			return leftType
360		case "**":
361			// Power operator requires numbers
362			if !isNumber(leftType) || !isNumber(rightType) {
363				c.addError("** operator requires numbers, got %s and %s",
364					leftType.String(), rightType.String())
365			}
366			return leftType
367		case "==", "!=":
368			// Equality operators work on all types
369			return TypeBool
370		case "<", ">", "<=", ">=":
371			// Comparison operators require numbers
372			if !isNumber(leftType) || !isNumber(rightType) {
373				c.addError("%s operator requires numbers, got %s and %s",
374					expr.Operator, leftType.String(), rightType.String())
375			}
376			return TypeBool
377		case "&&", "||":
378			// Logical operators require booleans
379			if !TypesEqual(leftType, TypeBool) || !TypesEqual(rightType, TypeBool) {
380				c.addError("%s operator requires booleans, got %s and %s",
381					expr.Operator, leftType.String(), rightType.String())
382			}
383			return TypeBool
384		case "&", "|", "^":
385			// Bitwise operators require integers
386			if !TypesEqual(leftType, TypeInt) || !TypesEqual(rightType, TypeInt) {
387				c.addError("%s operator requires integers, got %s and %s",
388					expr.Operator, leftType.String(), rightType.String())
389			}
390			return TypeInt
391		case "<<", ">>":
392			// Shift operators require integers
393			if !TypesEqual(leftType, TypeInt) || !TypesEqual(rightType, TypeInt) {
394				c.addError("%s operator requires integers, got %s and %s",
395					expr.Operator, leftType.String(), rightType.String())
396			}
397			return TypeInt
398		default:
399			c.addError("unknown infix operator: %s", expr.Operator)
400			return TypeAny
401		}
402	}
