404	// checkCallExpression checks a function call
405	func (c *Checker) checkCallExpression(expr *ast.CallExpression) Type {
406		funcType := c.checkExpression(expr.Function)
407	
408		if funcType == nil {
409			return TypeAny
410		}
411	
412		// Function type check
413		if funcType, ok := funcType.(*FunctionType); ok {
414			// Check argument count
415			if len(expr.Arguments) != len(funcType.ParameterTypes) {
416				c.addError("function call expects %d arguments, got %d",
417					len(funcType.ParameterTypes), len(expr.Arguments))
418			}
419	
420			// Check argument types
421			for i, arg := range expr.Arguments {
422				argType := c.checkExpression(arg)
423				if i < len(funcType.ParameterTypes) {
424					if !IsCompatible(argType, funcType.ParameterTypes[i]) {
425						c.addError("argument %d has wrong type: expected %s, got %s",
426							i, funcType.ParameterTypes[i].String(), argType.String())
427					}
428				}
429			}
430	
431			return funcType.ReturnType
432		}
433	
434		c.addError("calling non-function type: %s", funcType.String())
435		return TypeAny
436	}
437	
438	// checkIndexExpression checks an index expression
439	func (c *Checker) checkIndexExpression(expr *ast.IndexExpression) Type {
440		leftType := c.checkExpression(expr.Left)
441		indexType := c.checkExpression(expr.Index)
442	
443		switch left := leftType.(type) {
444		case *ArrayType:
445			if !TypesEqual(indexType, TypeInt) && !TypesEqual(indexType, TypeAny) {
446				c.addError("array index must be int, got %s", indexType.String())
447			}
448			return left.ElementType
449	
450		case *HashType:
451			if !IsCompatible(indexType, left.KeyType) {
452				c.addError("hash key has wrong type: expected %s, got %s",
453					left.KeyType.String(), indexType.String())
454			}
455			return left.ValueType
456	
457		default:
458			c.addError("cannot index type %s", leftType.String())
459			return TypeAny
460		}
461	}
462	
463	// checkAssignmentExpression checks an assignment expression
464	func (c *Checker) checkAssignmentExpression(expr *ast.AssignmentExpression) Type {
465		// Get target type
466		var targetType Type
467	
468		if ident, ok := expr.Left.(*ast.Identifier); ok {
469			symbol, ok := c.symtab.Resolve(ident.Value)
470			if !ok {
471				c.addError("undefined variable: %q", ident.Value)
472				return TypeAny
473			}
474	
475			if !symbol.Mutable {
476				c.addError("cannot assign to immutable variable: %q", ident.Value)
477				return TypeAny
478			}
479	
480			targetType = symbol.Type
481		} else {
482			// For complex assignments (array[i] = value, obj.prop = value), infer from value
483			targetType = c.checkExpression(expr.Left)
484		}
485	
486		// Check value type compatibility
487		valueType := c.checkExpression(expr.Value)
488		if !IsCompatible(valueType, targetType) {
489			c.addError("cannot assign %s to %s", valueType.String(), targetType.String())
490		}
491	
492		return targetType
493	}
